discrete MagneticFieldDetection
port:
    event input real StartSignal;
    event input real StopSignal;
    event output real MagneticData;
state:
    initial state State1
        when entry() then
            statehold(5);
        end;
        when receive(StartSignal) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State3);
            out
                send(MagneticData, 1);
        end;
        when receive(StopSignal) then
            transition(State1);
        end;
    end;

    state State3
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State2);
        end;
    end;
end;
end;

discrete SignalProcessing
port:
    event input real ValidData;
    event input real PauseSignal;
    event output real ProcessedData;
state:
    initial state State1
