        end;
        when receive(ValidData) then
            transition(State2);
        end;
    end;

    state State2
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State3);
            out
                send(ProcessedData, 1);
        end;
        when receive(PauseSignal) then
            transition(State1);
        end;
    end;

    state State3
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State2);
        end;
    end;
end;
end;

